    @Test
    /**
     * Full Create-Read-Update-Delete of a DataSource, through a DataSourceTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on DataSourceTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on DataSourceTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new DataSource.
     *
     * @return    DataSource
     */
    public DataSource testCreate() throws Throwable {
    DataSource entity = null;

    LOGGER.info( "DataSourceTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a DataSource");

    StringBuilder msg = new StringBuilder( "-- Failed to create a DataSource" );

    try {
        entity = service.createDataSource( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDataSourceId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a DataSource with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a DataSource.
     *
     * @return    DataSource
     */
    public DataSource testRead() throws Throwable {
    LOGGER.info( "DataSourceTest:testRead()" );
    LOGGER.info( "-- Reading a previously created DataSource" );

    DataSource entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read DataSource with primary key" );
    msg.append( theId );

    try {
        entity = service.getDataSource( new DataSourceFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getDataSourceId();

        LOGGER.info( "-- Successfully found DataSource " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a DataSource.
     *
     * @return    DataSource
     */
    public DataSource testUpdate() throws Throwable {
    LOGGER.info( "DataSourceTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a DataSource." );

    StringBuilder msg = new StringBuilder( "Failed to update a DataSource : " );
    DataSource entity = null;

    try {
        UpdateDataSourceCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setDataSourceId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created DataSource." );

        entity = service.updateDataSource( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved DataSource - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a DataSource.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "DataSourceTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created DataSource." );

    try {
        DeleteDataSourceCommand deleteCommand = new DeleteDataSourceCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted DataSource with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete DataSource with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all DataSources.
     *
     * @return    Collection
     */
    public List<DataSource> testGetAll() throws Throwable {
    LOGGER.info( "DataSourceTest:testGetAll() - Retrieving Collection of DataSources:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataSource : " );
    List<DataSource> collection  = null;

    try {
        // call the static get method on the DataSourceService
        collection = service.getAllDataSource();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataSource currEntity  = null;
            Iterator<DataSource> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataSourceId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public DataSourceTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


